// BLE kapı zili: düğmeye basınca telefona "zil" bildirimi gider, buzzer çalar.
// Telefondan "sessiz" yazılınca buzzer susar, yalnız LED yanıp söner; "sesli" ile ses geri gelir.
// Telefona "nRF Connect" ya da "LightBlue" uygulamasını kur, KendinYap-Zil'e bağlan.
#include <BLEDevice.h>
#include <BLEServer.h>
#include <BLEUtils.h>
#include <BLE2902.h>

#define SERVIS_UUID "6e1a0001-4b2c-4d6a-9f3e-2a7c5b8d1e01"
#define ZIL_UUID    "6e1a0002-4b2c-4d6a-9f3e-2a7c5b8d1e01"  // okuma + bildirim: "zil"
#define MOD_UUID    "6e1a0003-4b2c-4d6a-9f3e-2a7c5b8d1e01"  // yazma: "sessiz" / "sesli"

const char* BLE_ADI = "KendinYap-Zil";
const int DUGME_PIN = 19;   // zil düğmesi (öbür ucu GND)
const int BUZZER_PIN = 18;  // buzzer +
const int LED_PIN = 4;      // zil LED'i
const unsigned long ZIL_ARALIGI_MS = 3000;  // art arda basışlarda en az 3 sn bekle

BLECharacteristic* zilOzelligi;
BLECharacteristic* modOzelligi;
bool telefonBagli = false;
bool sessiz = false;
int sonDugme = HIGH;
unsigned long sonZil = 0;
bool hicCalmadi = true;

class SunucuOlaylari : public BLEServerCallbacks {
  void onConnect(BLEServer*) override {
    telefonBagli = true;
    Serial.println("Telefon baglandi");
  }
  void onDisconnect(BLEServer* s) override {
    telefonBagli = false;
    Serial.println("Telefon ayrildi");
    s->startAdvertising();  // tekrar görünür ol
  }
};

class ModOlaylari : public BLECharacteristicCallbacks {
  void onWrite(BLECharacteristic* c) override {
    String deger = c->getValue();
    deger.trim();
    deger.toLowerCase();
    if (deger == "sessiz") sessiz = true;
    else if (deger == "sesli") sessiz = false;
    else return;
    c->setValue(sessiz ? "sessiz" : "sesli");
    Serial.println(sessiz ? "Mod: sessiz" : "Mod: sesli");
  }
};

void zilCal() {
  zilOzelligi->setValue("zil");
  if (telefonBagli) zilOzelligi->notify();
  Serial.println(telefonBagli ? "Zil! Telefona bildirildi." : "Zil! (telefon bagli degil)");

  if (sessiz) {
    // Sessiz mod: yalnız LED 3 kez yanıp söner.
    for (int i = 0; i < 3; i++) {
      digitalWrite(LED_PIN, HIGH);
      delay(200);
      digitalWrite(LED_PIN, LOW);
      delay(200);
    }
  } else {
    // Ding-dong: iki ton, LED de yanar.
    digitalWrite(LED_PIN, HIGH);
    tone(BUZZER_PIN, 1047, 350);
    delay(400);
    tone(BUZZER_PIN, 784, 500);
    delay(550);
    digitalWrite(LED_PIN, LOW);
  }
}

void setup() {
  Serial.begin(115200);
  pinMode(DUGME_PIN, INPUT_PULLUP);
  pinMode(BUZZER_PIN, OUTPUT);
  pinMode(LED_PIN, OUTPUT);

  BLEDevice::init(BLE_ADI);
  BLEServer* sunucu = BLEDevice::createServer();
  sunucu->setCallbacks(new SunucuOlaylari());
  BLEService* servis = sunucu->createService(SERVIS_UUID);

  zilOzelligi = servis->createCharacteristic(ZIL_UUID, BLECharacteristic::PROPERTY_READ | BLECharacteristic::PROPERTY_NOTIFY);
  zilOzelligi->addDescriptor(new BLE2902());
  zilOzelligi->setValue("bekliyor");

  modOzelligi = servis->createCharacteristic(MOD_UUID, BLECharacteristic::PROPERTY_READ | BLECharacteristic::PROPERTY_WRITE);
  modOzelligi->setCallbacks(new ModOlaylari());
  modOzelligi->setValue("sesli");

  servis->start();
  BLEAdvertising* yayin = BLEDevice::getAdvertising();
  yayin->addServiceUUID(SERVIS_UUID);
  BLEDevice::startAdvertising();
  Serial.printf("BLE hazir: %s\n", BLE_ADI);
}

void loop() {
  int dugme = digitalRead(DUGME_PIN);
  bool basildi = dugme == LOW && sonDugme == HIGH;  // yalnız basıldığı an
  sonDugme = dugme;
  if (basildi && (hicCalmadi || millis() - sonZil > ZIL_ARALIGI_MS)) {
    hicCalmadi = false;
    sonZil = millis();
    zilCal();
  }
  delay(20);
}
